def post(vals, sep, result):
    if not isinstance(result, list) or len(result) != len(vals) + len(vals) - 1:
        return False
    for i in range(len(result)):
        if i > 0 and result[i] != vals[i-1]:
            return False
        if i < len(result) - 1 and (i % 2 == 0 or i >= len(vals)) and result[i] != sep:
            return False
    return True

def is_consecutive(lst):
    return all(lst[i] + 1 == lst[i+1] for i in range(len(lst)-1))

def is_sep_incorrectly_placed(result, vals):
    for i in range(len(result)):
        if (i > 0 and result[i] != vals[i-1]) or \
           (i < len(result) - 1 and (i % 2 == 0 or i >= len(vals)) and result[i] != sep):
            return True
    return False

def is_sep_missing(result, vals):
    for i in range(len(result)):
